<template><section><div class="title"><h1>{{ categoryName }}</h1><span>共有 {{ total }} 个</span></div><VideoGrid :items="items"/><Pagination :page="page" :pages="pages" @change="go"/></section></template><script setup>import {computed,ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {getCategoryVideos,normalizeList} from '../api/vod';import VideoGrid from '../components/VideoGrid.vue';import Pagination from '../components/Pagination.vue';import menu from '../config/menu.json';const r=useRoute(),router=useRouter(),items=ref([]),page=ref(1),pages=ref(1),total=ref(0);const categoryName=computed(()=>{const id=Number(r.params.id);for(const row of menu.rows||[]){const item=(row.items||[]).find(x=>Number(x.id)===id);if(item)return item.name}return '视频分类'});async function load(){page.value=Math.max(1,Number(r.query.page||1));try{const x=await getCategoryVideos(r.params.id,page.value);items.value=normalizeList(x);pages.value=Number(x.pagecount||x.page_count||1);total.value=Number(x.total||x.totalnum||x.recordcount||x.count||x.data?.total||x.data?.totalnum||x.data?.recordcount||items.value.length||0)}catch{items.value=[];total.value=0}}function go(n){router.push({query:{page:n}})}onMounted(load);watch(()=>r.params.id,load);watch(()=>r.query.page,load)</script>
